    op: DT::WriteOperation,
    context_ghost: Tracked<FCClientRequestResponseGhost<DT>>,
) -> (res: (bool, Tracked<FCClientRequestResponseGhost<DT>>))
    requires
        context_ghost@.enqueue_op_pre(
            self.thread_id_g@,
